// ignore_for_file: invalid_annotation_target
import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:mobi_shared_types/models/vehicle_type.dart';

part 'trip.freezed.dart';
part 'trip.g.dart';

/// Represents the lifecycle status of a trip.
enum TripStatus {
  @JsonValue('active')
  active,
  @JsonValue('cancelled')
  cancelled,
  @JsonValue('completed')
  completed,
}

@freezed
abstract class Trip with _$Trip {
  const Trip._();

  const factory Trip({
    /// UUID primary key (auto-generated by Supabase).
    String? id,

    /// The user who created this trip.
    @JsonKey(name: 'author_id') required String authorId,

    /// Display name of the author (for mock data / UI display).
    @JsonKey(name: 'author_name') @Default('') String authorName,

    /// Human-readable origin label.
    required String origin,

    /// Origin latitude.
    @JsonKey(name: 'origin_lat') double? originLat,

    /// Origin longitude.
    @JsonKey(name: 'origin_lng') double? originLng,

    /// Human-readable destination label.
    required String destination,

    /// Destination latitude.
    @JsonKey(name: 'dest_lat') double? destLat,

    /// Destination longitude.
    @JsonKey(name: 'dest_lng') double? destLng,

    /// Departure date (ISO 8601 date string e.g. '2026-03-25').
    @JsonKey(name: 'departure_date') @Default('') String departureDate,

    /// Departure time (e.g. '08:30 AM' or '14:30').
    @JsonKey(name: 'departure_time') @Default('') String departureTime,

    /// Legacy fields kept for backward compat with existing UI screens.
    @Default('') String date,
    @Default('') String time,

    /// 'passenger' or 'driver'.
    @Default('passenger') String role,

    /// WhatsApp phone number (legacy UI field).
    @Default('') String whatsapp,

    /// Available seats (legacy UI field).
    @Default(1) int seats,

    /// Display price/distance text (legacy UI field).
    String? price,

    /// Optional note / special instructions.
    String? note,

    /// Optional description (legacy).
    String? description,

    /// Whether this trip is active (legacy UI field).
    @JsonKey(name: 'is_active') @Default(true) bool isActive,

    /// String status (legacy: 'pending'|'approved'|'suspended'|'blocked').
    String? status,

    /// Vehicle type enum.
    VehicleType? vehicleType,

    /// Vehicle type as string (for Supabase serialization).
    @JsonKey(name: 'vehicle_type') @Default('cab') String vehicleTypeStr,

    /// Whether this trip repeats weekly.
    @JsonKey(name: 'is_recurring') @Default(false) bool isRecurring,

    /// Day indices (0=Mon..6=Sun) for recurring trips.
    @JsonKey(name: 'recurring_days') @Default([]) List<int> recurringDays,

    /// Joined date display (legacy UI).
    String? joinedDate,

    /// Server-managed timestamps.
    @JsonKey(name: 'created_at') String? createdAt,
    @JsonKey(name: 'updated_at') String? updatedAt,
  }) = _Trip;

  factory Trip.fromJson(Map<String, dynamic> json) => _$TripFromJson(json);

  /// Returns the effective vehicle type, preferring the enum if set.
  VehicleType get effectiveVehicleType {
    if (vehicleType != null) return vehicleType!;
    switch (vehicleTypeStr) {
      case 'moto':
        return VehicleType.moto;
      case 'trike':
        return VehicleType.trike;
      case 'truck':
        return VehicleType.truck;
      case 'private':
        return VehicleType.private_;
      case 'cab':
      default:
        return VehicleType.cab;
    }
  }
}
